def apply_edits(text, edits):
    it = iter(edits)
    result = []
    i = 0
    n = len(text)
    while i < n:
        if not it:
            result.append(text[i:])
            break
        start, end, repl = next(it)
        if i < start:
            result.append(text[i:start])
            i = start
        if i == start:
            result.append(repl)
            i = end
        else:
            i += 1
    return ''.join(result)
